// Hora local de Neiva, calculada explicitamente y no heredada del
// servidor: si esto dependiera de UTC, "las diez de la noche" serian en
// realidad las cinco de la tarde.
const INICIO = 7;   // inclusivo
const CIERRE = 22;  // exclusivo: a las 22:00 en punto ya no sale nada

const hora = Number(new Intl.DateTimeFormat('en-GB', {
  timeZone: 'America/Bogota', hour: '2-digit', hour12: false,
}).format(new Date()));

const dentro = hora >= INICIO && hora < CIERRE;
const manual = $execution.mode === 'test';

// Las ejecuciones PROGRAMADAS se cortan aqui: fuera de hora no tiene sentido
// molestar al backend. Las MANUALES si pasan, para poder probar la cadena a
// cualquier hora — y no debilita nada, porque Laravel comprueba la misma
// ventana con su propio reloj y se niega a enviar igual.
if (!dentro && !manual) {
  return [];
}

return [{ json: {
  hora_local: hora,
  zona: 'America/Bogota',
  ventana: '07:00-22:00',
  dentro_de_ventana: dentro,
  modo: $execution.mode,
} }];

const r = $input.first()?.json ?? {};
const status = r.statusCode ?? 0;
const body = r.body ?? {};

if (status === 401 || status === 403) {
  return [{ json: { resultado: 'credencial', status, alerta: true,
    mensaje: 'Laravel rechazo la credencial. Revisar AUTOMATION_INTERNAL_SECRET en n8n y en el backend.' } }];
}

if (status === 409 && body.reason === 'wellness_disabled') {
  return [{ json: { resultado: 'inerte', status, alerta: false,
    mensaje: 'Modulo de bienestar apagado en el servidor (NOTIFICATIONS_WELLNESS_ENABLED=false).' } }];
}

if (status === 429) {
  return [{ json: { resultado: 'limitado', status, alerta: true,
    mensaje: 'Demasiadas peticiones. No reintentar en bucle.' } }];
}

if (status >= 500) {
  return [{ json: { resultado: 'error_servidor', status, alerta: true,
    mensaje: 'El backend fallo. La idempotencia diaria evita duplicados al reintentar.' } }];
}

if (status !== 200 || body.ok !== true) {
  return [{ json: { resultado: 'fallo', status, alerta: true,
    mensaje: body.message || 'Laravel no acepto la tanda.' } }];
}

if (body.skipped === 'outside_window') {
  return [{ json: { resultado: 'fuera_de_ventana', status, alerta: false,
    mensaje: body.message, proxima_apertura: body.next_opening ?? null } }];
}

// `enviados` cuenta telefonos que sonaron en ESTA tanda. Lo que ya estaba
// resuelto de una pasada anterior del mismo dia va aparte: la segunda tanda
// diaria no manda nada por diseno, y sumarlo como envio hacia que el numero
// dijera tres cuando solo habia sonado uno.
return [{ json: {
  resultado: 'ok',
  status,
  considerados: body.considered ?? 0,
  enviados: body.sent ?? 0,
  no_enviados: body.suppressed ?? 0,
  ya_resueltos: body.already_handled ?? 0,
  hora_local: body.window?.local_hour ?? null,
  alerta: false,
  nota: 'enviados = telefonos que sonaron ahora. ya_resueltos = socios que ya tenian su aviso de hoy. no_enviados = preferencias, horas de silencio o limites de frecuencia.',
} }];
